// ----------------------------------------------------------------------------
// RECORDED ANSWERS for the DNS-over-HTTPS lookup's golden vectors (generated by
// the build notes' make_fixtures.py; do not edit by hand). Each body is a real
// answer, captured from this container on 2026-10-27 between 10:25 and 10:39
// São Paulo (the ECH and compact-denial answers at 11:44; DNS.SB's, Control
// D's and the three answers to POST at 15:21), by an RFC 8484 GET with ?dns=
// and Accept: application/dns-message to the resolver named (or, for a fixture
// marked POST, an RFC 8484 POST with the query as its body and Content-Type
// application/dns-message),
// for a documentation name (example.com, www.example: RFC 2606; a.example.com,
// RFC 9824's own nonexistent-name example), a name the operator's documentation
// gives (cloudflare-ech.com, dns.google, the resolvers' own addresses), or the
// RFC 9462 discovery name _dns.resolver.arpa. The query sent is recorded too,
// base64 as sent.
//
// THE EXPECTATIONS ARE NOT THIS MODULE'S OWN OUTPUT: each body was replayed to
// dig through a local UDP responder, and `expect` is dig's own decoding
// (status, flags, every record), normalised in three documented ways only:
// base64 and hex fields without the spaces dig inserts, NXNAME where dig
// prints TYPE128, and dohpath where it prints key7 (both IANA names, RFC 9824
// and RFC 9461, newer than dig's tables).
// The oracle: dig 9.18.39 (Ubuntu's package) on 2026-10-27 for the first run;
// all 28 bodies replayed again the same evening to dig 9.20.30, built from
// ISC's signed source (BIND 9.18 reached end of life in 2026; 9.20 is ISC's
// current stable branch), with the same options: every status, flag line and
// record line identical, TYPE128 and key7 included, so these expectations
// stand unchanged.
//
// PRIME DIRECTIVE (D-19): every line commented.
// ============================================================================

/** One recorded answer and dig's decoding of it. */
export interface RecordedAnswer {
  /** The fixture's id. */
  id: string;
  /** The resolver asked (an id from RESOLVERS). */
  resolver: string;
  /** The name typed (an address for PTR). */
  name: string;
  /** The type asked for. */
  type: string;
  /** POST when the answer came back to a POST (absent: a GET). */
  method?: "POST";
  /** EDNS(0) with padding was on. */
  edns: boolean;
  /** DO was set. */
  dnssecOk: boolean;
  /** CD was set. */
  checkingDisabled: boolean;
  /** What the fixture shows. */
  shows: string;
  /** The query as sent, base64. */
  query: string;
  /** The answer as received, base64. */
  body: string;
  /** SHA-256 of the answer, hex. */
  sha256: string;
  /** dig's status. */
  status: string;
  /** dig's flags, in dig's order. */
  flags: string[];
  /** dig's records (answer, authority, additional), normalised as the header says. */
  expect: string[];
}

